import {createSession,createModel,loadModel,packModel,packSession,loadSession,trainingStats} from './learning.js?v=9';
const $=id=>document.getElementById(id);
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('gomulda-zero',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function dbRead(db){return new Promise((resolve,reject)=>{const r=db.transaction('state').objectStore('state').get('learning');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function dbWrite(db,value,key='learning'){return new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
export async function initLearningLab({onChange=()=>{}}={}){
 let session=null,arena=null,db=null,worker=null,running=false,kind='',saveQueue=Promise.resolve(),warning='',status='',ready=false;
 function draw(){if(!session)return;const stats=trainingStats(session.model);$('learn-role-counts').textContent=`Training history: ${stats.selfPlay.toLocaleString()} self-play rounds · against Search: ${stats.searchWhite.toLocaleString()} as White, ${stats.searchBlack.toLocaleString()} as Black.`;const againstSearch=$('learn-mode').value==='search';$('learn-search-setting').hidden=!againstSearch;$('learn-mode-note').textContent=againstSearch?'Zero alternates White (create costly maps) and Black (keep maps cheap). An odd-sized run resumes with the other role next time. Only Zero learns; Search stays fixed.':'Zero plays both roles in every round, learning from its own search and the final colouring score.';$('learn-games').textContent=session.model.games.toLocaleString();$('learn-updates').textContent=session.model.updates.toLocaleString();$('learn-rule').textContent=session.model.extraCost;$('learn-model-status').textContent=warning||status||'Experimental checkpoint. Gomulda Search remains the default.';
  for(const id of ['learn-start','learn-evaluate','learn-export','learn-rounds','learn-simulations','learn-import','learn-mode','learn-search-ms'])$(id).disabled=!ready||running;$('learn-stop').hidden=!running;$('learn-stop').disabled=false;$('learn-stop').textContent=kind==='evaluate'?'Stop after this match':'Stop after this round';
  const svg=$('learning-chart'),ns='http://www.w3.org/2000/svg';svg.replaceChildren();const h=session.history.slice(-100);if(h.length>1){const max=Math.max(.001,...h.map(x=>x.valueLoss));const line=document.createElementNS(ns,'polyline');line.setAttribute('points',h.map((p,i)=>`${12+i*496/(h.length-1)},${116-p.valueLoss/max*100}`).join(' '));line.setAttribute('fill','none');line.setAttribute('stroke','#516f49');line.setAttribute('stroke-width','2');svg.append(line);}else{const t=document.createElementNS(ns,'text');t.setAttribute('x','16');t.setAttribute('y','70');t.setAttribute('fill','#6c7c63');t.setAttribute('font-size','13');t.textContent='Train to see prediction loss over time.';svg.append(t);}
  if(arena){const a=arena.summary;$('arena-summary').textContent=`Checkpoint after ${arena.modelGames} rounds: ${a.wins} wins, ${a.draws} draws, ${a.losses} losses against Search. Mean score margin ${a.meanMargin.toFixed(2)}. ${a.strongerEvidence?'Positive evidence at this test budget; test more positions before drawing broader conclusions.':'No established advantage over Gomulda Search.'}${arena.modelGames!==session.model.games?' This tests an earlier checkpoint.':''}`;const table=document.createElement('table');const head=table.createTHead().insertRow();for(const text of ['Match','Zero as White','Search as White','Margin']){const th=document.createElement('th');th.textContent=text;head.append(th);}arena.results.forEach((r,i)=>{const row=table.insertRow();[i+1,r.learnerWhite,r.opponentWhite,r.margin].forEach(x=>row.insertCell().textContent=x);});$('arena-results').replaceChildren(table);}else{$('arena-summary').textContent='No local test for this checkpoint yet. Gomulda Search remains the default.';$('arena-results').replaceChildren();}
 }
 function persist(){if(!db){warning='Training is held in memory. Export a checkpoint to keep it.';draw();return;}const snapshot={session,arena};saveQueue=saveQueue.then(()=>dbWrite(db,snapshot)).catch(()=>{warning='Local saving failed. Export a checkpoint to keep this training.';draw();});}
 function fail(error){running=false;worker?.terminate();worker=null;$('learn-progress-text').textContent=error.message;draw();}
 function launch(command){if(!ready||running)return;running=true;kind=command;worker=new Worker(new URL('./learning-worker.js?v=9',import.meta.url),{type:'module'});$('learn-progress').hidden=false;$('learn-progress').value=0;$('learn-progress-text').textContent=command==='train'?($('learn-mode').value==='search'?'Training against Search, alternating both roles…':'Generating self-play rounds…'):'Testing a frozen checkpoint against Search…';draw();worker.onerror=()=>fail(Error('The learning worker stopped. Completed checkpoints are retained.'));
  worker.onmessage=({data})=>{if(data.error){fail(Error(data.error));return;}if(data.kind==='training'){session=data.session;status='Training checkpoint saved on this device.';const r=data.result;$('learn-progress-text').textContent=`${data.completed}/${data.total} rounds · ${r.mode==='search'?`Zero as ${r.learnerRole==='white'?'White':'Black'} vs Search`:'self-play'} · last penalty ${r.penalty} · value loss ${r.valueLoss.toFixed(4)}`;persist();onChange();}else if(data.kind==='evaluation'){arena={results:data.results,summary:data.summary,modelGames:data.modelGames};$('learn-progress-text').textContent=`${data.completed}/8 paired test matches complete`;persist();}else if(data.kind==='done'){running=false;worker.terminate();worker=null;$('learn-progress-text').textContent=data.stopped?'Stopped. Completed training and tests are retained.':command==='train'?'Training complete. Test this checkpoint against Search.':'Strength test complete.';persist();}
   if(data.total){$('learn-progress').max=data.total;$('learn-progress').value=data.completed;}draw();};
  worker.postMessage(command==='train'?{command,session,games:Number($('learn-rounds').value),simulations:Number($('learn-simulations').value),mode:$('learn-mode').value,searchTimeMs:Number($('learn-search-ms').value)}:{command,model:session.model});
 }
 $('learn-mode').onchange=draw;
 $('learn-start').onclick=()=>launch('train');$('learn-evaluate').onclick=()=>launch('evaluate');$('learn-stop').onclick=()=>{worker?.postMessage({command:'stop'});$('learn-stop').disabled=true;$('learn-progress-text').textContent='Stopping after the current round or test match…';};
 $('learn-export').onclick=()=>{const blob=new Blob([JSON.stringify({...packSession(session),arena})],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`gomulda-zero-${session.model.games}-rounds.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 $('learn-import').onchange=async()=>{try{const file=$('learn-import').files[0];if(!file)return;if(file.size>30*1024*1024)throw Error('Checkpoint is too large (maximum 30 MB).');const raw=JSON.parse(await file.text());session=loadSession(raw);arena=null;warning='';status='Imported checkpoint. Run a new strength test for this model.';persist();draw();onChange();}catch(e){$('learn-progress-text').textContent=e.message;}finally{$('learn-import').value='';}};
 try{db=await openDB();const stored=await dbRead(db);if(stored){if(stored.session?.model?.extraCost!==25){await dbWrite(db,stored,'before-fixed-rule');warning='Your checkpoint used older custom colour costs and was backed up on this device. The fixed-rule pilot is loaded below.';}else{session=loadSession(stored.session);arena=stored.arena;status='Resumed your saved local checkpoint.';}}}catch{warning='Local storage is unavailable. Export checkpoints to keep your training.';}
 if(!session){try{const response=await fetch('./zero-pilot.json');if(!response.ok)throw Error('No pilot');session=createSession(loadModel(await response.json()));status=`Loaded the ${session.model.games}-round experimental pilot. Further training stays on this device.`;try{const r=await fetch('./zero-pilot-arena.json');if(r.ok)arena=await r.json();}catch{}}catch{session=createSession(createModel({seed:9132026}));status='New untrained network. Start self-play training to update it.';}}
 ready=true;draw();onChange();return {getModel(extraCost){if(session.model.extraCost!==extraCost)throw Error(`Gomulda Zero was trained with sixth-colour cost ${session.model.extraCost}. Gomulda now uses the fixed cost of 25; import a compatible checkpoint.`);return packModel(session.model);},read(){return {ready,running,games:session.model.games,updates:session.model.updates,extraCost:session.model.extraCost,trainingStats:trainingStats(session.model),trainingMode:$('learn-mode').value,arena:arena?.summary??null};},train(){launch('train');return {started:running};}};
}
